#!/bin/sh
# Install Lunar: one file, just run it.
#
#   * Double-click it (if your file manager asks, choose "Execute"), or
#   * run:  sh Install-Lunar.sh        (add --demo to click through without installing)
#
# It opens a window that installs the Lunar desktop. If your system is missing
# the small piece it needs to draw that window, it asks before installing it.
#
# (This file is generated by installer/make-single-file.sh: this shell launcher
# followed by lunar-installer.py.)

# ---- small helpers: show messages in a window even when started by a click ----

have() { command -v "$1" >/dev/null 2>&1; }

notice() { # title, message
    if have kdialog; then kdialog --title "$1" --msgbox "$2"
    elif have zenity; then zenity --info --title="$1" --text="$2" --width=420
    else printf '%s\n\n%s\n' "$1" "$2" >&2; fi
}

ask() { # title, question; succeeds on "yes"
    if have kdialog; then kdialog --title "$1" --yesno "$2"
    elif have zenity; then zenity --question --title="$1" --text="$2" --width=420
    else
        printf '%s [y/N] ' "$2" >&2
        read -r answer || return 1
        case $answer in y | Y | yes | YES) return 0 ;; *) return 1 ;; esac
    fi
}

# ---- find Python with GTK 4 ----

python=${LUNAR_PYTHON:-}
if [ -z "$python" ]; then
    for candidate in python3 python; do
        if have "$candidate"; then python=$candidate; break; fi
    done
fi

has_gtk() {
    [ -n "$python" ] && "$python" -c \
        "import gi; gi.require_version('Gtk', '4.0'); from gi.repository import Gtk" \
        >/dev/null 2>&1
}

is_fedora() {
    osrel=${LUNAR_OS_RELEASE:-/etc/os-release}
    [ -r "$osrel" ] || return 1
    # shellcheck disable=SC1091
    . "$osrel"
    case " ${ID:-} ${ID_LIKE:-} " in *" fedora "*) return 0 ;; esac
    return 1
}

if ! has_gtk; then
    if is_fedora && have pkexec && have dnf; then
        if ask "Install Lunar" \
            "Lunar's installer needs a small package (Python GTK 4 bindings) that isn't on this computer yet.

Install it now? You'll be asked for your password."; then
            pkexec dnf install -y python3-gobject gtk4 || true
            # Whatever python3 was found before may have been replaced; look again.
            [ -n "${LUNAR_PYTHON:-}" ] || python=python3
        else
            exit 0
        fi
    fi
fi

if ! has_gtk; then
    notice "Install Lunar" \
        "Lunar's installer needs Python 3 with the GTK 4 bindings (python3-gobject and gtk4 on Fedora).

Please install them, then open this file again."
    exit 1
fi

# ---- refuse to run as root (the installer asks for a password itself) ----

case " $* " in
    *" --demo "*) ;;
    *)
        if [ "$(id -u)" = 0 ]; then
            notice "Install Lunar" \
                "Please run this as your normal user, not as root. It asks for your password only when it needs it."
            exit 1
        fi
        ;;
esac

# ---- unpack the installer and run it ----

workdir=$(mktemp -d "${TMPDIR:-/tmp}/lunar-installer.XXXXXX") || exit 1
trap 'rm -rf "$workdir"' EXIT INT TERM
sed '1,/^#__LUNAR_INSTALLER_PYTHON__$/d' "$0" >"$workdir/lunar-installer.py"

# Started from a file manager there is no terminal to show errors in, so keep
# them in a log file and say where it is.
logfile=${XDG_CACHE_HOME:-$HOME/.cache}/lunar-installer/launcher.log
if [ -t 2 ]; then
    "$python" "$workdir/lunar-installer.py" "$@"
    status=$?
else
    mkdir -p "$(dirname "$logfile")" 2>/dev/null
    "$python" "$workdir/lunar-installer.py" "$@" 2>"$logfile"
    status=$?
fi
if [ "$status" -ne 0 ]; then
    notice "Install Lunar" \
        "The installer closed unexpectedly (exit status $status).

Details were saved to:
$logfile"
fi
exit "$status"
#__LUNAR_INSTALLER_PYTHON__
#!/usr/bin/env python3
"""Lunar installer: a small GTK 4 window that installs the Lunar desktop.

It runs on top of any desktop (needs only Python 3 with PyGObject and GTK 4),
and installs, in this order:

  * the build dependencies           (one password prompt, via pkexec)
  * the Lunar desktop, from GitHub   (cloned and built as your user)
  * the KWin glass effect            (optional; built from source)
  * system files + login-screen entry (second and last password prompt)
  * the WhiteSur icon theme          (optional; into ~/.local/share/icons)

Supported system: Fedora with KDE Plasma 6 (dnf). Run it with --demo to click
through the whole flow without changing anything.

    python3 lunar-installer.py            # install for real
    python3 lunar-installer.py --demo     # pretend (no changes at all)
"""

import argparse
import base64
import os
import shlex
import signal
import subprocess
import sys
import threading
import time
from pathlib import Path

import gi

gi.require_version("Gtk", "4.0")
gi.require_version("Gdk", "4.0")
from gi.repository import Gdk, Gio, GLib, Gtk  # noqa: E402

APP_ID = "org.lunar.Installer"

LUNAR_REPO = os.environ.get("LUNAR_REPO", "https://github.com/craft2guardian/Sonoma-desktop.git")
GLASS_REPO = os.environ.get("LUNAR_GLASS_REPO", "https://github.com/4v3ngR/kwin-effects-glass")
ICONS_REPO = os.environ.get("LUNAR_ICONS_REPO", "https://github.com/vinceliuice/WhiteSur-icon-theme")

HOME = Path.home()
WORK = Path(os.environ.get("LUNAR_INSTALLER_DIR", HOME / ".local/share/lunar-installer"))
LOG_FILE = Path(os.environ.get("XDG_CACHE_HOME", HOME / ".cache")) / "lunar-installer" / "install.log"

# Everything the build needs on Fedora. `--skip-unavailable` means a package
# that doesn't exist on this release is skipped instead of failing the whole
# transaction; the build step then says clearly what is missing.
FEDORA_PACKAGES = [
    "git", "gcc", "gcc-c++", "make", "cmake", "pkgconf-pkg-config", "extra-cmake-modules",
    "rust", "cargo",
    "gtk4-devel", "gtk4-layer-shell-devel", "wayland-devel", "wayland-protocols-devel",
    "kwin-devel", "libepoxy-devel", "libdrm-devel", "vulkan-headers",
    "kf6-ki18n-devel", "kf6-kguiaddons-devel", "kf6-kcmutils-devel", "cmake(KDecoration3)",
    "glslc", "glslang",
    "kf6-kconfig", "mako",
]


# --------------------------------------------------------------------------
# The install job: a list of steps run on a worker thread
# --------------------------------------------------------------------------

class Cancelled(Exception):
    pass


class StepError(Exception):
    pass


class Step:
    def __init__(self, title, seconds, run):
        self.title = title        # shown under the progress bar
        self.seconds = seconds    # rough expected duration; also the weight
        self.run = run


class Job:
    """Runs the steps and exposes progress for the UI to poll."""

    def __init__(self, options, demo):
        self.options = options
        self.demo = demo
        self.steps = self._plan()
        self.index = 0
        self.step_started = time.monotonic()
        self.cancelled = False
        self.process = None
        self.lines = []           # log lines not yet shown
        self.lock = threading.Lock()
        self.log_file = None
        self.result = None        # None while running, then "done" / "error" / "cancelled"
        self.error = ""

    # ---- planning ----

    def _plan(self):
        o = self.options
        steps = [
            Step("Checking your system…", 2, self.check_system),
            Step("Installing build tools…", 150, self.install_packages),
            Step("Downloading Lunar…", 25, self.fetch_lunar),
            Step("Building Lunar…", 480, self.build_lunar),
        ]
        if o["glass"]:
            steps += [
                Step("Downloading the glass effect…", 15, self.fetch_glass),
                Step("Building the glass effect…", 150, self.build_glass),
            ]
        if o["icons"]:
            steps.append(Step("Installing WhiteSur icons…", 70, self.install_icons))
        steps.append(Step("Installing Lunar…", 20, self.install_system))
        if o["glass"]:
            steps.append(Step("Turning on the glass effect…", 3, self.enable_glass))
        return steps

    # ---- progress, read by the UI ----

    def total_seconds(self):
        return sum(step.seconds for step in self.steps)

    def progress(self):
        """(fraction 0–1, seconds remaining, title of the current step)."""
        total = self.total_seconds()
        if self.result == "done":
            return 1.0, 0.0, "Done"
        index = min(self.index, len(self.steps) - 1)
        step = self.steps[index]
        elapsed = time.monotonic() - self.step_started
        # Inside a step we only know roughly how long it takes, so creep towards
        # (but never reach) the end of its share rather than pretend precision.
        inside = min(0.95, elapsed / step.seconds) if step.seconds else 0.0
        done = sum(s.seconds for s in self.steps[:index]) + step.seconds * inside
        left_in_step = max(step.seconds * (1 - inside), 20 if step.seconds > 60 else 2)
        remaining = left_in_step + sum(s.seconds for s in self.steps[index + 1:])
        return done / total, remaining, step.title

    # ---- logging and commands ----

    def log(self, line):
        line = line.rstrip("\n")
        with self.lock:
            self.lines.append(line)
        if self.log_file:
            self.log_file.write(line + "\n")
            self.log_file.flush()

    def take_lines(self):
        with self.lock:
            lines, self.lines = self.lines, []
        return lines

    def check_cancelled(self):
        if self.cancelled:
            raise Cancelled()

    def sleep(self, seconds):
        """Interruptible sleep (demo mode)."""
        end = time.monotonic() + seconds
        while time.monotonic() < end:
            self.check_cancelled()
            time.sleep(0.05)

    def sh(self, command, cwd=None, allow_fail=False):
        """Runs a command, streaming its output to the log."""
        self.check_cancelled()
        shown = " ".join(shlex.quote(str(part)) for part in command)
        self.log(f"$ {shown}")
        if self.demo:
            self.sleep(0.35)
            return 0
        try:
            self.process = subprocess.Popen(
                [str(part) for part in command],
                cwd=cwd,
                stdout=subprocess.PIPE,
                stderr=subprocess.STDOUT,
                stdin=subprocess.DEVNULL,
                text=True,
                errors="replace",
                start_new_session=True,
            )
        except FileNotFoundError:
            if allow_fail:
                self.log(f"(skipped: {command[0]} is not installed)")
                return 127
            raise StepError(f"{command[0]} is not installed") from None
        for line in self.process.stdout:
            self.log(line)
            if self.cancelled:
                self.kill()
        code = self.process.wait()
        self.process = None
        self.check_cancelled()
        if code != 0 and not allow_fail:
            raise StepError(f"“{command[0]}” stopped with an error (exit status {code}).")
        return code

    def kill(self):
        process = self.process
        if process and process.poll() is None:
            try:
                os.killpg(process.pid, signal.SIGTERM)
            except (ProcessLookupError, PermissionError):
                pass

    def cancel(self):
        self.cancelled = True
        self.kill()

    # ---- the steps ----

    def check_system(self):
        if self.demo:
            self.sh(["echo", "Fedora Linux with KDE Plasma 6"])
            self.sleep(0.8)
            return
        release = {}
        try:
            for line in Path("/etc/os-release").read_text().splitlines():
                if "=" in line:
                    key, _, value = line.partition("=")
                    release[key] = value.strip('"')
        except OSError:
            pass
        names = f"{release.get('ID', '')} {release.get('ID_LIKE', '')}".split()
        self.log(f"System: {release.get('PRETTY_NAME', 'unknown')}")
        if "fedora" not in names:
            raise StepError("This installer supports Fedora for now. "
                            "On other systems, follow the steps in the project README.")
        for tool in ("dnf", "pkexec", "git"):
            if not self._which(tool):
                raise StepError(f"“{tool}” was not found, and the installer needs it.")
        self.sh(["plasmashell", "--version"], allow_fail=True)
        if os.environ.get("XDG_SESSION_TYPE") == "x11":
            self.log("Note: Lunar needs a Wayland session to run; you are on X11 now.")

    @staticmethod
    def _which(tool):
        for directory in os.environ.get("PATH", "").split(os.pathsep):
            if os.access(os.path.join(directory, tool), os.X_OK):
                return True
        return False

    def install_packages(self):
        self.sh(["pkexec", "dnf", "install", "-y", "--skip-unavailable", *FEDORA_PACKAGES])

    def _fetch(self, url, destination):
        if not self.demo:
            WORK.mkdir(parents=True, exist_ok=True)
        if (destination / ".git").exists() and not self.demo:
            self.sh(["git", "-C", destination, "pull", "--ff-only"])
        else:
            self.sh(["git", "clone", "--depth", "1", url, destination])

    def fetch_lunar(self):
        self._fetch(LUNAR_REPO, WORK / "lunar")

    def build_lunar(self):
        self.sh(["cargo", "build", "--release"], cwd=WORK / "lunar")

    def fetch_glass(self):
        self._fetch(GLASS_REPO, WORK / "kwin-effects-glass")

    def build_glass(self):
        source = WORK / "kwin-effects-glass"
        self.sh(["cmake", "-S", source, "-B", source / "build",
                 "-DCMAKE_INSTALL_PREFIX=/usr", "-DCMAKE_BUILD_TYPE=Release"])
        self.sh(["cmake", "--build", source / "build", f"-j{os.cpu_count() or 2}"])

    def install_icons(self):
        source = WORK / "whitesur-icons"
        self._fetch(ICONS_REPO, source)
        target = HOME / ".local/share/icons"
        if not self.demo:
            target.mkdir(parents=True, exist_ok=True)
        self.sh(["./install.sh", "-d", target], cwd=source)
        self.sh(["kwriteconfig6", "--file", "kdeglobals", "--group", "Icons",
                 "--key", "Theme", "WhiteSur"], allow_fail=True)
        self.sh(["gsettings", "set", "org.gnome.desktop.interface", "icon-theme", "WhiteSur"],
                allow_fail=True)

    def install_system(self):
        """Everything that needs root, in one prompt."""
        lunar = shlex.quote(str(WORK / "lunar"))
        script = f"set -e; sh {lunar}/session/install.sh --prefix /usr/local"
        if self.options["glass"]:
            glass = shlex.quote(str(WORK / "kwin-effects-glass" / "build"))
            script += f"; cmake --install {glass}"
        self.sh(["pkexec", "sh", "-ec", script])

    def enable_glass(self):
        # Our glass effect replaces KWin's own Blur, so the two must not both run.
        settings = [
            ("Plugins", "glassEnabled", "true"),
            ("Plugins", "blurEnabled", "false"),
            ("Effect-blurplus", "BlurStrength", "4"),
            ("Effect-blurplus", "DockBlurStrength", "4"),
        ]
        for group, key, value in settings:
            self.sh(["kwriteconfig6", "--file", "kwinrc", "--group", group,
                     "--key", key, value], allow_fail=True)
        for method, effect in (("unloadEffect", "blur"), ("loadEffect", "glass")):
            self.sh(["dbus-send", "--session", "--dest=org.kde.KWin", "--type=method_call",
                     "/Effects", f"org.kde.kwin.Effects.{method}", f"string:{effect}"],
                    allow_fail=True)

    # ---- worker ----

    def run(self):
        try:
            if not self.demo:
                LOG_FILE.parent.mkdir(parents=True, exist_ok=True)
                self.log_file = open(LOG_FILE, "w", encoding="utf-8")
            for index, step in enumerate(self.steps):
                self.index = index
                self.step_started = time.monotonic()
                self.log(f"\n== {step.title.rstrip('…')} ==")
                step.run()
                if self.demo:
                    self.sleep(self._demo_length(step))
            self.result = "done"
        except Cancelled:
            self.log("\nInstallation cancelled.")
            self.result = "cancelled"
        except StepError as error:
            self.error = str(error)
            self.log(f"\nError: {error}")
            self.result = "error"
        except Exception as error:  # a bug here should be shown, not swallowed
            self.error = f"Unexpected error: {error}"
            self.log(f"\n{self.error}")
            self.result = "error"
        finally:
            if self.log_file:
                self.log_file.close()

    @staticmethod
    def _demo_length(step):
        # Demo mode runs about 40x faster than a real install.
        return max(0.4, step.seconds / 40)


