def _logo_texture():
    try:
        data = base64.b64decode("".join(LOGO_PNG_BASE64.split()))
        return Gdk.Texture.new_from_bytes(GLib.Bytes.new(data))
    except Exception:
        return None


_LOGO_TEXTURE = None


class LogoImage(Gtk.Widget):
    """Draws the logo texture at exactly size x size, centred, no matter how
    large the image file is (Gtk.Picture would grow to the image's own size)."""

    def __init__(self, texture, size):
        super().__init__(halign=Gtk.Align.CENTER, valign=Gtk.Align.CENTER,
                         hexpand=False, vexpand=False)
        self.texture = texture
        self.size = size

    def do_measure(self, orientation, for_size):
        return self.size, self.size, -1, -1

    def do_snapshot(self, snapshot):
        self.texture.snapshot(snapshot, self.size, self.size)


def logo(size):
    """The Lunar logo, drawn from the embedded PNG (CSS moon if it can't load)."""
    global _LOGO_TEXTURE
    if _LOGO_TEXTURE is None:
        _LOGO_TEXTURE = _logo_texture()
    if _LOGO_TEXTURE is not None:
        return LogoImage(_LOGO_TEXTURE, size)
    outer = widget(Gtk.Box, "logo", "logo-fallback", halign=Gtk.Align.CENTER)
    outer.set_size_request(size, size)
    moon = widget(Gtk.Box, "logo-moon", halign=Gtk.Align.CENTER, valign=Gtk.Align.CENTER)
    moon.set_size_request(int(size * 0.5), int(size * 0.5))
    outer.set_halign(Gtk.Align.CENTER)
    outer.set_valign(Gtk.Align.CENTER)
    centre = Gtk.CenterBox()
    centre.set_center_widget(moon)
    centre.set_hexpand(True)
    centre.set_vexpand(True)
    outer.append(centre)
    return outer


def status_icon(kind, glyph):
    box = widget(Gtk.Label, "status-icon", kind, label=glyph, halign=Gtk.Align.CENTER)
    box.set_size_request(88, 88)
    return box


def spacer():
    return widget(Gtk.Box, vexpand=True)


# --------------------------------------------------------------------------
# The window
# --------------------------------------------------------------------------

class Installer(Gtk.Window):
    def __init__(self, app, demo):
        super().__init__(application=app, title="Install Lunar")
        self.demo = demo
        self.job = None
        self.thread = None
        self.poll = None
        self.add_css_class("installer")
        self.set_default_size(800, 640)
        self.set_resizable(False)

        self.options = {"glass": True, "icons": True}

        self.set_titlebar(self._lights())
        self.stack = Gtk.Stack(transition_type=Gtk.StackTransitionType.NONE)
        self.set_child(self.stack)
        self.stack.add_named(self._welcome_page(), "welcome")
        self.stack.add_named(self._options_page(), "options")
        self.stack.add_named(self._progress_page(), "progress")
        self.stack.add_named(self._done_page(), "done")
        self.stack.add_named(self._error_page(), "error")
        self.connect("close-request", self._on_close_request)

    # ---- chrome ----

    def _lights(self):
        handle = Gtk.WindowHandle()
        row = widget(Gtk.Box, "lights", orientation=Gtk.Orientation.HORIZONTAL)
        close = widget(Gtk.Button, "light", "close", focusable=False, tooltip_text="Close")
        close.connect("clicked", lambda *_: self._request_quit())
        row.append(close)
        for name in ("minimize", "maximize"):
            dot = widget(Gtk.Button, "light", name, focusable=False, sensitive=True)
            dot.set_can_target(False)  # decorative, like the originals' greyed-out buttons
            row.append(dot)
        handle.set_child(row)
        return handle

    # ---- pages ----

    def _page(self, *children, margin=56):
        page = widget(Gtk.Box, orientation=Gtk.Orientation.VERTICAL, spacing=0)
        page.set_margin_start(margin)
        page.set_margin_end(margin)
        page.set_margin_bottom(34)
        for child in children:
            page.append(child)
        return page

    def _buttons(self, *buttons):
        row = widget(Gtk.Box, orientation=Gtk.Orientation.HORIZONTAL, spacing=12, halign=Gtk.Align.CENTER)
        for button in buttons:
            row.append(button)
        return row

    def _pill(self, text, callback, primary=False):
        b = widget(Gtk.Button, "pill", label=text)
        if primary:
            b.add_css_class("primary")
        b.connect("clicked", lambda *_: callback())
        return b

    def _welcome_page(self):
        box = widget(Gtk.Box, orientation=Gtk.Orientation.VERTICAL, spacing=14, halign=Gtk.Align.CENTER)
        box.append(logo(150))
        box.append(widget(Gtk.Box, margin_top=10))
        box.append(label("Lunar Desktop", "installer-title"))
        box.append(label("Lunar Desktop will be installed on this computer."
                         "", "installer-text", width=46))
        return self._page(spacer(), box, spacer(),
                          self._buttons(self._pill("Continue", lambda: self.show("options"), True)))

    def _option_row(self, cls, glyph, title, subtitle, key=None):
        row = widget(Gtk.Box, "row", orientation=Gtk.Orientation.HORIZONTAL, spacing=14)
        icon = widget(Gtk.Label, "row-icon", cls, label=glyph)
        icon.set_size_request(34, 34)
        row.append(icon)
        text = widget(Gtk.Box, orientation=Gtk.Orientation.VERTICAL, spacing=2, hexpand=True, valign=Gtk.Align.CENTER)
        text.append(label(title, "row-title", justify=Gtk.Justification.LEFT))
        text.append(label(subtitle, "installer-dim", justify=Gtk.Justification.LEFT))
        for child in (text.get_first_child(), text.get_last_child()):
            child.set_halign(Gtk.Align.START)
            child.set_xalign(0)
        row.append(text)
        switch = Gtk.Switch(valign=Gtk.Align.CENTER, active=True)
        if key is None:
            switch.set_sensitive(False)
        else:
            switch.connect("notify::active", lambda s, _p: self.options.__setitem__(key, s.get_active()))
        row.append(switch)
        return row

    def _options_page(self):
        card = widget(Gtk.Box, "card", orientation=Gtk.Orientation.VERTICAL)
        card.append(self._option_row("lunar", "L", "Lunar desktop",
                                     "The shell, session entry and dock icons. Always installed."))
        card.append(widget(Gtk.Box, "row-sep"))
        card.append(self._option_row("glass", "◐", "Liquid glass effect (Recomended)",
                                     "Blur and refraction for the dock and windows. Built from source.", "glass"))
        card.append(widget(Gtk.Box, "row-sep"))
        card.append(self._option_row("icons", "◆", "WhiteSur icon theme",
                                     "macOS-style icons, installed for your user only.", "icons"))

        note = label("You’ll be asked for your password twice. Nothing is changed in your current "
                     "Plasma session; Lunar appears as its own entry at the login screen.",
                     "installer-dim", width=62)
        head = widget(Gtk.Box, orientation=Gtk.Orientation.VERTICAL, spacing=8, margin_bottom=22)
        head.append(label("Choose what to install", "installer-title"))
        head.append(label("Downloaded from GitHub and built on this computer.", "installer-text"))

        return self._page(
            widget(Gtk.Box, margin_top=26), head, card, widget(Gtk.Box, margin_top=18), note, spacer(),
            self._buttons(self._pill("Back", lambda: self.show("welcome")),
                          self._pill("Install", self.start_install, True)),
            margin=64)

    def _progress_page(self):
        box = widget(Gtk.Box, orientation=Gtk.Orientation.VERTICAL, spacing=12, halign=Gtk.Align.CENTER)
        box.append(logo(112))
        box.append(widget(Gtk.Box, margin_top=8))
        box.append(label("Installing Lunar", "installer-title"))
        self.step_label = label("Getting ready…", "installer-text", width=50)
        box.append(self.step_label)

        self.bar = Gtk.ProgressBar(halign=Gtk.Align.CENTER, margin_top=22)
        self.bar.set_size_request(320, 6)
        box.append(self.bar)
        self.time_label = label("", "installer-dim")
        box.append(self.time_label)

        self.log_view = widget(Gtk.TextView, "log", editable=False, cursor_visible=False,
                               monospace=True, wrap_mode=Gtk.WrapMode.WORD_CHAR,
                               left_margin=10, right_margin=10, top_margin=8, bottom_margin=8)
        scroll = Gtk.ScrolledWindow(hscrollbar_policy=Gtk.PolicyType.NEVER, min_content_height=150, max_content_height=150)
        scroll.set_child(self.log_view)
        self.log_scroll = scroll
        self.revealer = Gtk.Revealer(transition_type=Gtk.RevealerTransitionType.SLIDE_DOWN)
        self.revealer.set_child(scroll)
        self.revealer.set_margin_top(10)

        self.details = widget(Gtk.Button, "link", label="Show Details", halign=Gtk.Align.CENTER)
        self.details.connect("clicked", self._toggle_details)
        self.cancel_button = self._pill("Cancel", self._request_quit)

        return self._page(spacer(), box, self.details, self.revealer, spacer(),
                          self._buttons(self.cancel_button), margin=64)

    def _done_page(self):
        box = widget(Gtk.Box, orientation=Gtk.Orientation.VERTICAL, spacing=12, halign=Gtk.Align.CENTER)
        box.append(status_icon("ok", "✓"))
        box.append(widget(Gtk.Box, margin_top=8))
        box.append(label("Lunar is installed", "installer-title"))
        box.append(label("Log out, then choose “Lunar” from the session menu on the login screen. "
                         "To go back, pick “Plasma” there; your normal desktop is untouched.",
                         "installer-text", width=48))
        return self._page(spacer(), box, spacer(),
                          self._buttons(self._pill("Not Now", self._quit),
                                        self._pill("Log Out", self._log_out, True)))

    def _error_page(self):
        box = widget(Gtk.Box, orientation=Gtk.Orientation.VERTICAL, spacing=12, halign=Gtk.Align.CENTER)
        box.append(status_icon("bad", "!"))
        box.append(widget(Gtk.Box, margin_top=8))
        box.append(label("Installation didn’t finish", "installer-title"))
        self.error_label = label("", "installer-text", width=50)
        box.append(self.error_label)
        self.error_hint = label("", "installer-dim", width=58)
        box.append(self.error_hint)
        return self._page(spacer(), box, spacer(),
                          self._buttons(self._pill("Quit", self._quit),
                                        self._pill("Try Again", lambda: self.show("options"), True)))

    # ---- navigation ----

    def show(self, name):
        self.stack.set_visible_child_name(name)

    def _toggle_details(self, _button):
        reveal = not self.revealer.get_reveal_child()
        self.revealer.set_reveal_child(reveal)
        self.details.set_label("Hide Details" if reveal else "Show Details")

    # ---- running the install ----

    def start_install(self):
        self.job = Job(dict(self.options), self.demo)
        self.log_view.get_buffer().set_text("")
        self.bar.set_fraction(0)
        self.time_label.set_text("Calculating time remaining…")
        self.step_label.set_text(self.job.steps[0].title)
        self.cancel_button.set_sensitive(True)
        self.show("progress")
        self.thread = threading.Thread(target=self.job.run, daemon=True)
        self.thread.start()
        self.poll = GLib.timeout_add(200, self._tick)

    def _tick(self):
        job = self.job
        lines = job.take_lines()
        if lines:
            buffer = self.log_view.get_buffer()
            buffer.insert(buffer.get_end_iter(), "\n".join(lines) + "\n")
            adjustment = self.log_scroll.get_vadjustment()
            GLib.idle_add(lambda: adjustment.set_value(adjustment.get_upper()))
        fraction, remaining, title = job.progress()
        self.bar.set_fraction(fraction)
        self.step_label.set_text(title)
        self.time_label.set_text(self._format_remaining(remaining))

        if job.result is None:
            return True
        self.poll = None
        if job.result == "done":
            self.bar.set_fraction(1)
            self.show("done")
        elif job.result == "error":
            self.error_label.set_text(job.error)
            self.error_hint.set_text("" if self.demo else f"The full log is saved at {LOG_FILE}.")
            self.show("error")
        else:
            self._quit()
        return False

    @staticmethod
    def _format_remaining(seconds):
        minutes = int((seconds + 59) // 60)
        if minutes <= 1:
            return "Less than a minute remaining" if seconds < 50 else "About 1 minute remaining"
        return f"About {minutes} minutes remaining"

    # ---- closing and cancelling ----

    def _running(self):
        return self.job is not None and self.job.result is None

    def _request_quit(self):
        if not self._running():
            self._quit()
            return
        dialog = Gtk.AlertDialog(message="Stop installing Lunar?",
                                 detail="Anything already installed stays; you can run the installer again later.",
                                 buttons=["Keep Installing", "Stop"], cancel_button=0, default_button=0)

        def answered(source, result):
            try:
                choice = source.choose_finish(result)
            except GLib.Error:
                return
            if choice == 1 and self._running():
                self.cancel_button.set_sensitive(False)
                self.step_label.set_text("Stopping…")
                self.job.cancel()

        dialog.choose(self, None, answered)

    def _on_close_request(self, _window):
        if self._running():
            self._request_quit()
            return True
        return False

    def _quit(self):
        self.get_application().quit()

    def _log_out(self):
        if not self.demo:
            subprocess.Popen(["dbus-send", "--session", "--dest=org.kde.Shutdown", "--type=method_call",
                              "/Shutdown", "org.kde.Shutdown.logout"],
                             stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL)
        self._quit()


class App(Gtk.Application):
    def __init__(self, demo):
        super().__init__(application_id=APP_ID, flags=Gio.ApplicationFlags.NON_UNIQUE)
        self.demo = demo
        self.window = None

    def do_activate(self):
        provider = Gtk.CssProvider()
        provider.load_from_string(CSS)
        Gtk.StyleContext.add_provider_for_display(
            Gdk.Display.get_default(), provider, Gtk.STYLE_PROVIDER_PRIORITY_APPLICATION)
        self.window = Installer(self, self.demo)
        self.window.present()


def main():
    parser = argparse.ArgumentParser(description="Install the Lunar desktop.")
    parser.add_argument("--demo", action="store_true",
                        help="click through the installer without changing anything")
    args = parser.parse_args()
    if os.geteuid() == 0 and not args.demo:
        sys.exit("Run this as your normal user, not root; it asks for a password when needed.")
    return App(args.demo).run([sys.argv[0]])


if __name__ == "__main__":
    sys.exit(main())
